<?php
namespace Tests\Feature;
use App\Models\FootballMatch;use App\Models\Team;use App\Models\User;use App\Services\PredictionScoringService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class MatchPredictionArenaTest extends TestCase{use RefreshDatabase;
 private function match():FootballMatch{$league=\DB::table('leagues')->insertGetId(['football_data_id'=>1,'name'=>'Premier League','short_code'=>'PL','created_at'=>now(),'updated_at'=>now()]);$home=Team::create(['football_data_id'=>101,'name'=>'Arsenal FC']);$away=Team::create(['football_data_id'=>102,'name'=>'Everton FC']);return FootballMatch::create(['football_data_id'=>5001,'league_id'=>$league,'league_football_data_id'=>1,'home_team_id'=>$home->id,'home_team_football_data_id'=>101,'away_team_id'=>$away->id,'away_team_football_data_id'=>102,'match_date'=>now()->addHour(),'status'=>'SCHEDULED']);}
 public function test_logged_in_user_can_make_and_edit_match_prediction():void{$match=$this->match();$user=User::factory()->create();$this->actingAs($user)->post(route('matches.prediction.store',$match),['home_score'=>2,'away_score'=>1])->assertRedirect();$this->actingAs($user)->post(route('matches.prediction.store',$match),['home_score'=>3,'away_score'=>1])->assertRedirect();$this->assertDatabaseCount('user_predictions',1);$this->assertDatabaseHas('user_predictions',['user_id'=>$user->id,'match_id'=>$match->id,'prediction_value'=>'3-1']);$this->get(route('matches.show',$match))->assertOk()->assertSee('3–1',false)->assertSee($user->name);}
 public function test_predictions_close_at_kickoff():void{$match=$this->match();$match->update(['match_date'=>now()->subMinute(),'status'=>'IN_PLAY']);$this->actingAs(User::factory()->create())->post(route('matches.prediction.store',$match),['home_score'=>1,'away_score'=>0])->assertStatus(422);$this->assertDatabaseCount('user_predictions',0);}
 public function test_admin_sponsor_prize_is_allocated_to_earliest_exact_winner():void{$match=$this->match();$admin=User::factory()->create(['is_admin'=>true]);$first=User::factory()->create();$second=User::factory()->create();$this->actingAs($admin)->post(route('admin.matches.sponsor.store',$match),['name'=>'NGR','website_url'=>'https://ngr.ltd','prize_title'=>'Signed shirt','prize_value'=>'£100','prize_quantity'=>1,'active'=>1])->assertRedirect();$this->actingAs($first)->post(route('matches.prediction.store',$match),['home_score'=>2,'away_score'=>0]);$this->travel(1)->seconds();$this->actingAs($second)->post(route('matches.prediction.store',$match),['home_score'=>2,'away_score'=>0]);$match->update(['match_date'=>now()->subHours(2),'status'=>'FINISHED','home_score'=>2,'away_score'=>0]);app(PredictionScoringService::class)->scoreMatchPredictions($match);$this->assertDatabaseHas('match_prize_awards',['user_id'=>$first->id,'status'=>'selected']);$this->assertDatabaseMissing('match_prize_awards',['user_id'=>$second->id]);$this->get(route('matches.show',$match))->assertOk()->assertSee('PRIZE WINNER',false)->assertSee('WINNER',false);}
}
